//! THE RATCHET: a crate root may not hold an inline `#[cfg(test)] mod … { … }`.
//!
//! Measured 2026-09-05 on develop: the 64 crate roots held 20,441 lines, and 12,488 of them (61%) sat
//! inside inline test modules. Those lines are not implementation and they are the reason a root reads
//! as a monolith — so they belong in the graph as `role: test` records, which is what
//! `the-crate-root-monoliths-are-61-percent-test-code` moved twelve crates' worth of.
//!
//! # Why a guard and not just the fix
//!
//! The fix repairs the twelve roots that were extracted. Nothing stops the thirteenth from growing a
//! new one, and nothing would say so: a root that re-grows an inline `mod tests` compiles, passes, and
//! is invisible to every other leg of the gate. This repo's signature failure is a gate that PASSES
//! while covering less than the reader assumes, and an inline test module is exactly that shape —
//! present, green, and outside the store the crate otherwise compiles from.
//!
//! # Why an allow-list rather than a count
//!
//! 33 roots still hold one, and they are being worked by several sessions at once. A COUNT would let a
//! session migrate one root and re-grow another with the total unchanged; a NAMED list cannot. The
//! assertion is SUBSET, not equality, so a session that cleans a root never has to edit this list to
//! stay green — the list may only shrink in effect, never grow, and pruning it is housekeeping rather
//! than a merge conflict for whoever lands first.
//!
//! # Why the population is asserted
//!
//! A scanner that silently stops matching reports ZERO offenders, and zero reads as a pass. So the
//! scan asserts it found the roots it expects to find before it says anything about what is in them.

use std::path::{Path, PathBuf};

/// The repo root — two levels above `crates/bsc-graph`.
fn repo_root() -> PathBuf {
    let root = Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .and_then(Path::parent)
        .expect("crates/<name> is two deep")
        .to_path_buf();
    assert!(
        std::fs::read_to_string(root.join("Cargo.toml")).is_ok_and(|t| t.contains("[workspace]")),
        "the workspace root must be two levels above this crate — found {}",
        root.display()
    );
    root
}

/// Every crate ROOT on disk, as `(repo-relative path, text)`.
///
/// A root is `src/lib.rs` or `src/main.rs` of a package — the file that is NOT reachable as a
/// declared child, and so the one file `bsc graph migrate-crate` leaves behind.
fn crate_roots(root: &Path) -> Vec<(String, String)> {
    let mut dirs: Vec<PathBuf> = vec![root.join("src-tauri")];
    if let Ok(entries) = std::fs::read_dir(root.join("crates")) {
        dirs.extend(entries.flatten().map(|e| e.path()).filter(|p| p.is_dir()));
    }
    let mut out = Vec::new();
    for d in dirs {
        for name in ["lib.rs", "main.rs"] {
            let p = d.join("src").join(name);
            if let Ok(t) = std::fs::read_to_string(&p) {
                out.push((p.strip_prefix(root).unwrap_or(&p).display().to_string().replace('\\', "/"), t));
            }
        }
    }
    out.sort();
    out
}

/// The names of the TOP-LEVEL `#[cfg(test)] mod <name> { … }` blocks in one file.
///
/// Column 0 only, which is what "top-level" means in a root — a `#[cfg(test)]` nested inside another
/// module is that module's business, and a root has no such modules once it is migrated. A trailing
/// `;` (a declared child, `mod tests;`) is deliberately NOT matched: that is the shape this guard
/// wants, one step before the record.
fn inline_test_mods(text: &str) -> Vec<String> {
    let lines: Vec<&str> = text.lines().collect();
    let mut out = Vec::new();
    for (i, l) in lines.iter().enumerate() {
        if *l != "#[cfg(test)]" {
            continue;
        }
        let Some(next) = lines.get(i + 1) else { continue };
        let rest = next
            .strip_prefix("pub(crate) ")
            .or_else(|| next.strip_prefix("pub(super) "))
            .or_else(|| next.strip_prefix("pub "))
            .unwrap_or(next);
        let Some(rest) = rest.strip_prefix("mod ") else { continue };
        let Some(name) = rest.strip_suffix('{') else { continue };
        let name = name.trim();
        if !name.is_empty() && name.chars().all(|c| c.is_alphanumeric() || c == '_') {
            out.push(name.to_string());
        }
    }
    out
}

/// The roots that still hold an inline test module.
///
/// SUBSET, not equality: cleaning a root never requires editing this list. Adding to it does — and
/// that edit is the conversation the guard exists to force.
///
/// IT WAS 33 AND IT IS 2. `migrate-crate --lift <mod>` is the verb that closed the gap the header
/// describes — 24 roots were driven through it in one pass, and 5 more had left the tree entirely
/// (their whole `src/` is records now, so there is no root file to scan). Each of the two that remain
/// is here for a SPECIFIC reason, written down beside it, rather than because nobody got to it.
const STILL_INLINE: &[&str] = &[
    // NOT WIRED. Neither of this crate's roots `include!`s the materialized crate, so a record lifted
    // out of `main.rs` would be compiled by nothing. `bsc graph migrate-crate bsc-lan --apply` is the
    // step that comes first, and `--lift` refuses until it has.
    "crates/bsc-lan/src/main.rs",
    // THE ID WOULD COLLIDE. `bsc-rf` has two roots, and BOTH spelled `mod tests`. The library one is a
    // record now (`bsc-rf--tests.rs`, derived from `crates/bsc-rf/src/tests.rs`), and the binary one
    // would derive the SAME id for a different module. Renaming one of the two is the fix, and it is a
    // decision about this crate rather than something the lift may take.
    "crates/bsc-rf/src/main.rs",
];

/// A crate root holds implementation, not tests.
///
/// The failure names the crate and the module, because "some root regressed" is not actionable — and
/// the fix is now ONE COMMAND rather than the six-step recipe this used to spell out:
///
/// ```text
/// bsc graph migrate-crate <crate> --lift <mod>            # the plan, writing nothing
/// bsc graph migrate-crate <crate> --lift <mod> --apply
/// ```
///
/// It authors the block as a `role: test` record carrying its `moduleVis` and `moduleAttrs`, harvests
/// it through the same path a file module takes, promotes exactly that id, reads the committed store
/// back, removes the block from the root, and verifies with `cargo check --all-targets`.
#[test]
fn a_crate_root_holds_no_inline_test_module() {
    let root = repo_root();
    let roots = crate_roots(&root);
    // A scanner that stops matching reports zero offenders, and zero reads as a pass.
    //
    // THE FLOOR ONLY EVER FALLS, and that is the migration working rather than the scan breaking: a
    // crate that reaches the real floor holds a `Cargo.toml` and nothing else, so it has no root file
    // to find. MEASURED 2026-09-05: 61 before `bsc-network`, `bsc-rf` and `bsc-sound` finished their
    // roots, 58 after — and 12 after `the-crate-root-implementations-move-into-the-graph` moved 46
    // more, of which 8 belong to the lanes exempted while they are mid-feature. Lower it when a crate
    // legitimately leaves — never raise it to make a red go away, because the number is here to catch
    // a scan that stopped matching.
    assert!(
        roots.len() >= 10,
        "found only {} crate roots — the scan is broken, so its verdict about inline test modules is \
         worthless",
        roots.len()
    );

    let mut offenders = Vec::new();
    for (path, text) in &roots {
        let mods = inline_test_mods(text);
        if !mods.is_empty() && !STILL_INLINE.contains(&path.as_str()) {
            offenders.push(format!("{path}: {}", mods.join(", ")));
        }
    }
    assert!(
        offenders.is_empty(),
        "these crate roots grew an inline `#[cfg(test)] mod` — a test module belongs in the graph as a \
         `role: test` record, not in the one file a migrated crate has left:\n  {}\n\n\
         Lift each one with:\n    \
         bsc graph migrate-crate <crate> --lift <mod> --root \"$PWD\"           # the plan\n    \
         bsc graph migrate-crate <crate> --lift <mod> --apply --root \"$PWD\"\n\
         ...and verify the test COUNT is unchanged under BOTH `cargo nextest run -p <crate>` and \
         `cargo test -p <crate> --lib`. The count is the only thing that sees a record promoted \
         without a body.",
        offenders.join("\n  ")
    );
}

/// The scan must actually FIND an inline test module where one exists, or the guard above passes for
/// the wrong reason forever.
///
/// Pinned on synthetic text rather than on a real file, so cleaning the last root in `STILL_INLINE`
/// does not turn this test into a tautology.
#[test]
fn the_scan_finds_a_block_and_ignores_the_shapes_that_are_not_one() {
    let found = inline_test_mods(
        "fn a() {}\n#[cfg(test)]\nmod tests {\n    #[test]\n    fn t() {}\n}\n\
         #[cfg(test)]\npub(crate) mod testhome {\n}\n",
    );
    assert_eq!(found, vec!["tests".to_string(), "testhome".to_string()]);

    // A DECLARED child is the shape this guard wants; it must not be reported.
    assert!(inline_test_mods("#[cfg(test)]\nmod tests;\n").is_empty(), "`mod tests;` is a declared child");
    // A `#[cfg(test)]` on anything that is not a module is not this guard's business.
    assert!(inline_test_mods("#[cfg(test)]\npub(crate) fn helper() {}\n").is_empty(), "a helper fn is fine");
    assert!(inline_test_mods("#[cfg(test)]\nuse std::fmt;\n").is_empty(), "a gated import is fine");
    // Nested (indented) modules belong to their parent, not to the root.
    assert!(inline_test_mods("mod outer {\n    #[cfg(test)]\n    mod tests {\n    }\n}\n").is_empty());
}
